package com.dukaops.backend.contact; import java.util.*; import org.springframework.data.domain.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; public interface CustomerRepository extends JpaRepository<Customer,UUID>{Optional<Customer> findByTenant_IdAndId(UUID t,UUID id); @Query("select c from Customer c where c.tenant.id=:t and (:q is null or lower(c.name) like lower(concat('%',:q,'%')) or lower(c.email) like lower(concat('%',:q,'%'))) and (:s is null or c.status=:s) order by c.name") Page<Customer> search(@Param("t")UUID t,@Param("q")String q,@Param("s")ContactStatus s,Pageable p); boolean existsByTenant_IdAndEmailIgnoreCase(UUID t,String e); boolean existsByTenant_IdAndEmailIgnoreCaseAndIdNot(UUID t,String e,UUID id);}
